  private static boolean flag(Map<String, Object> source, String key) {
    Object value = source.get(key);
    if (value == null) {
      return false;
    }
    if (value instanceof Boolean b) {
      return b;
    }
    throw DynamicClientException.invalidClientMetadata(key + " must be a boolean");
  }

  @SuppressWarnings("unchecked")
  private static Map<String, Object> object(Map<String, Object> source, String key) {
    Object value = source.get(key);
    if (value == null) {
      return null;
    }
    if (value instanceof Map<?, ?> map) {
      return (Map<String, Object>) map;
    }
    throw DynamicClientException.invalidClientMetadata(key + " must be an object");
  }

  private static List<String> list(Map<String, Object> source, String key) {
    Object value = source.get(key);
    if (value == null) {
      return null;
    }
    if (!(value instanceof List<?> items)) {
      throw DynamicClientException.invalidClientMetadata(key + " must be an array");
    }
    List<String> result = new ArrayList<>();
    for (Object item : items) {
      if (!(item instanceof String s)) {
        throw DynamicClientException.invalidClientMetadata(key + " must contain strings");
      }
      result.add(s);
    }
    return result;
  }

  private static Response error(DynamicClientException ex) {
    Response.ResponseBuilder builder = Response.status(ex.getStatus())
        .entity(Map.of("error", ex.getErrorCode(), "error_description", ex.getMessage()));
    if (ex.getStatus() == 401) {
      builder.header("WWW-Authenticate", "Bearer error=\"invalid_token\"");
    }
    return noStore(builder);
  }

  private static Response noStore(Response.ResponseBuilder builder) {
    return builder.type(MediaType.APPLICATION_JSON).header("Cache-Control", "no-store")
        .header("Pragma", "no-cache").build();
  }
